import { apiPost, HttpRequestError } from "../utils/api";
import { useNavigate } from "react-router-dom";
import { useState } from "react";
import InputField from "../components/InputField";
import FlashMessage from "../components/FlashMessage";

const RegistrationPage = () => {
    const nav = useNavigate(); // Hook for redirecting users after registration
    const [errorMessageState, setErrorMessageState] = useState(null); // Error message state
    const [valuesState, setValuesState] = useState({
        password: "", 
        confirmPassword: "", 
        email: ""
    });

    // Handles form submission
    const handleSubmit = (e) => {
        e.preventDefault();

        // Check if passwords match before sending data
        if (valuesState.password !== valuesState.confirmPassword) {
            setErrorMessageState("Hesla se neshodují"); // Show error message if passwords don't match
            return;
        }

        const { confirmPassword, ...registrationData } = valuesState; // Exclude confirmPassword from submission

        apiPost("/api/user", registrationData)
            .then(() => {
                nav("/login"); // Redirect user to login page after successful registration
            }).catch(e => {
                if (e instanceof HttpRequestError && e.response.status === 400) {
                    e.response.text().then(message => setErrorMessageState(message));
                    return;
                }
                setErrorMessageState("Při komunikaci se serverem nastala chyba.");
            });
    };

    // Handles input field changes
    const handleChange = (e) => {
        const fieldName = e.target.name;
        setValuesState({ ...valuesState, [fieldName]: e.target.value });
    };

    return (
        <div className="offset-4 col-sm-6 mt-5">
            <h1>Registrace</h1>
            <form onSubmit={handleSubmit}>
                {errorMessageState ? <FlashMessage theme={"danger"} text={errorMessageState} /> : null}
                <InputField
                    type="email"
                    name="email"
                    label="E-mail"
                    prompt="Zadejte Váš E-mail"
                    value={valuesState.email}
                    handleChange={handleChange}
                />
                <InputField
                    type="password"
                    name="password"
                    label="Heslo"
                    prompt="Zadejte Vaše heslo"
                    min={6}
                    value={valuesState.password}
                    handleChange={handleChange}
                />
                <InputField
                    type="password"
                    name="confirmPassword"
                    label="Heslo znovu"
                    prompt="Zadejte Vaše heslo znovu"
                    value={valuesState.confirmPassword}
                    handleChange={handleChange}
                />
                <input type="submit" className="btn btn-primary mt-2" value="Registrovat se"/>
            </form>
        </div>
    );
}

export default RegistrationPage;
